package com.gaurav.datasave;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.*;import android.view.*;import android.widget.*;import org.json.*;
public class MainActivity extends Activity{
 LinearLayout list; android.content.SharedPreferences sp; int green=Color.rgb(0,255,82), dark=Color.rgb(0,28,22);
 TextView tx(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setPadding(18,12,18,12);return v;}
 GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);g.setStroke(2,green);return g;}
 EditText field(String h){EditText e=new EditText(this);e.setHint(h);e.setHintTextColor(Color.LTGRAY);e.setTextColor(Color.WHITE);e.setSingleLine(true);e.setPadding(18,8,18,8);e.setBackground(bg(Color.rgb(5,49,39),18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,58);p.setMargins(0,6,0,6);e.setLayoutParams(p);return e;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setBackground(bg(Color.rgb(0,90,58),22));return b;}
 public void onCreate(Bundle b){super.onCreate(b);sp=getSharedPreferences("shops",0);draw();}
 void draw(){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(dark);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(18,18,18,30);
 TextView logo=tx("GAURAV\nDATA SAVE",30);logo.setGravity(17);logo.setTextColor(green);root.addView(logo);TextView tag=tx("SAVE TODAY  •  GROW TOMORROW",12);tag.setGravity(17);root.addView(tag);
 LinearLayout stats=new LinearLayout(this);String[] ss={"🏪 Total Shops","👥 Visited","⭐ Favourites","📍 Today"};for(String s:ss){TextView x=tx(s,14);x.setGravity(17);x.setBackground(bg(Color.rgb(0,70,55),20));stats.addView(x,new LinearLayout.LayoutParams(0,70,1));}root.addView(stats);
 EditText search=field("🔍 Search shop, phone, area, category...");root.addView(search);
 TextView add=tx("＋  Add Shop / Party",21);add.setTextColor(green);root.addView(add);
 EditText n=field("🏪 Shop / Party Name");root.addView(n);EditText p=field("☎ Phone Number");p.setInputType(3);root.addView(p);EditText m=field("🔗 Google Maps Location / Link");root.addView(m);EditText a=field("📍 Area (e.g. Paharganj, Delhi)");root.addView(a);EditText c=field("▦ Category");root.addView(c);EditText no=field("📝 Note (optional)");root.addView(no);
 Button save=btn("💾  SAVE LOCATION");save.setTextSize(18);root.addView(save,new LinearLayout.LayoutParams(-1,68));TextView title=tx("SAVED SHOPS",18);title.setTextColor(green);root.addView(title);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);
 save.setOnClickListener(v->{if(n.getText().toString().trim().isEmpty()){Toast.makeText(this,"Shop name required",0).show();return;}try{JSONArray ar=new JSONArray(sp.getString("data","[]"));JSONObject o=new JSONObject();o.put("n",n.getText().toString());o.put("p",p.getText().toString());o.put("m",m.getText().toString());o.put("a",a.getText().toString());o.put("c",c.getText().toString());o.put("no",no.getText().toString());ar.put(o);sp.edit().putString("data",ar.toString()).apply();draw();}catch(Exception e){}});
 search.setOnEditorActionListener((v,id,event)->{render(search.getText().toString());return false;});render("");sc.addView(root);setContentView(sc);}
 void render(String q){list.removeAllViews();try{JSONArray ar=new JSONArray(sp.getString("data","[]"));for(int i=ar.length()-1;i>=0;i--){JSONObject o=ar.getJSONObject(i);String all=o.toString().toLowerCase();if(!q.isEmpty()&&!all.contains(q.toLowerCase()))continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(14,10,14,10);card.setBackground(bg(Color.rgb(3,45,36),18));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,6,0,6);card.setLayoutParams(cp);TextView h=tx(o.optString("n"),19);h.setTextColor(green);card.addView(h);card.addView(tx("☎ "+o.optString("p")+"   📍 "+o.optString("a")+"\n"+o.optString("c")+"  "+o.optString("no"),14));LinearLayout row=new LinearLayout(this);String ph=o.optString("p"),mp=o.optString("m");Button call=btn("☎ Call");call.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+ph))));row.addView(call,new LinearLayout.LayoutParams(0,55,1));Button wa=btn("WhatsApp");wa.setOnClickListener(v->{String z=ph.replaceAll("\\D","");if(z.length()==10)z="91"+z;startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://wa.me/"+z)));});row.addView(wa,new LinearLayout.LayoutParams(0,55,1));Button map=btn("📍 Map");map.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(mp)));}catch(Exception e){}});row.addView(map,new LinearLayout.LayoutParams(0,55,1));card.addView(row);list.addView(card);}}catch(Exception e){}}
}